//! Error types for Bivvy operations.
//!
//! This module defines [`BivvyError`], the primary error type used throughout
//! the application, and a [`Result`] type alias for convenience.
//!
//! # Error Handling Strategy
//!
//! All modules use `BivvyError` with domain-specific variants. Each variant
//! provides actionable messages for users. Use `map_err` to convert
//! third-party error types into the appropriate `BivvyError` variant.

use std::path::PathBuf;
use thiserror::Error;

/// Core error type for Bivvy operations.
#[derive(Debug, Error)]
pub enum BivvyError {
    /// Configuration file not found at expected location.
    #[error("Configuration not found: {path}")]
    ConfigNotFound { path: PathBuf },

    /// Failed to parse configuration file.
    #[error("Failed to parse config at {path}: {message}")]
    ConfigParseError { path: PathBuf, message: String },

    /// Invalid configuration structure or values.
    #[error("Invalid configuration: {message}")]
    ConfigValidationError { message: String },

    /// Referenced template does not exist.
    #[error("Unknown template: {name}")]
    UnknownTemplate { name: String },

    /// Step dependency cycle detected.
    #[error("Circular dependency detected: {cycle}")]
    CircularDependency { cycle: String },

