        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let id1 = SessionId::new();
        let mut meta1 = SessionMetadata::new("list", vec![]);
        meta1.finalize(0, String::new(), String::new());
        store
            .save(&Session {
                id: id1,
