230→        let mut entry = store.store("http:test", "template", "content", 0).unwrap();
231→        entry.metadata.commit_sha = Some("abc123".to_string());
232→        store.update(&entry).unwrap();
233→
234→        let validator = CacheValidator::new(&store);
235→        let result = validator
236→            .validate("http:test", "template", RemoteCacheStrategy::Git)
237→            .unwrap();
238→
239→        assert_eq!(result, ValidationResult::NeedsRevalidation);
