  1→//! Cache storage implementation.
  2→
  3→use crate::error::{BivvyError, Result};
  4→use sha2::{Digest, Sha256};
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→
  8→use super::entry::CacheEntry;
  9→
 10→/// Storage for cached templates.
 11→pub struct CacheStore {
 12→    /// Root directory for cache.
 13→    root: PathBuf,
 14→}
 15→
 16→impl CacheStore {
 17→    /// Create a new cache store.
 18→    pub fn new(root: impl Into<PathBuf>) -> Self {
 19→        Self { root: root.into() }
 20→    }
 21→
 22→    /// Get the cache root directory.
 23→    pub fn root(&self) -> &Path {
 24→        &self.root
 25→    }
 26→
 27→    /// Ensure the cache directory exists.
 28→    fn ensure_dir(&self) -> Result<()> {
 29→        fs::create_dir_all(&self.root)?;
 30→        Ok(())
 31→    }
 32→
 33→    /// Get the path for storing an entry's content.
 34→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 35→        let key = format!("{}:{}", source_id, template_name);
 36→        let hash = Sha256::digest(key.as_bytes());
 37→        let hash_str = hex::encode(&hash[..16]);
 38→        self.root.join(hash_str)
 39→    }
 40→
 41→    /// Get the metadata file path for an entry.
 42→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 43→        self.content_path(source_id, template_name)
 44→            .with_extension("meta.json")
 45→    }
 46→
 47→    /// Store content and return a cache entry.
 48→    pub fn store(
 49→        &self,
 50→        source_id: &str,
 51→        template_name: &str,
 52→        content: &str,
 53→        ttl_seconds: u64,
 54→    ) -> Result<CacheEntry> {
 55→        self.ensure_dir()?;
 56→
 57→        let content_path = self.content_path(source_id, template_name);
 58→        fs::write(&content_path, content)?;
 59→
 60→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 61→            .with_size(content.len() as u64);
 62→
 63→        self.save_metadata(&entry)?;
 64→
 65→        Ok(entry)
 66→    }
 67→
 68→    /// Load a cached entry's metadata.
 69→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 70→        let meta_path = self.metadata_path(source_id, template_name);
 71→
 72→        if !meta_path.exists() {
 73→            return Ok(None);
 74→        }
 75→
 76→        let json = fs::read_to_string(&meta_path)?;
 77→        let entry: CacheEntry = serde_json::from_str(&json).map_err(|e| BivvyError::Serialization { message: e.to_string() })?;
 78→
 79→        Ok(Some(entry))
 80→    }
 81→
 82→    /// Read the cached content.
 83→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
 84→        Ok(fs::read_to_string(&entry.content_path)?)
 85→    }
 86→
 87→    /// Save entry metadata.
 88→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
 89→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
 90→        let json = serde_json::to_string_pretty(entry).map_err(|e| BivvyError::Serialization { message: e.to_string() })?;
 91→        fs::write(&meta_path, json)?;
 92→        Ok(())
 93→    }
 94→
 95→    /// Update an entry's metadata (e.g., after revalidation).
 96→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
 97→        self.save_metadata(entry)
 98→    }
 99→
100→    /// Remove a cached entry.
101→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
102→        let content_path = self.content_path(source_id, template_name);
103→        let meta_path = self.metadata_path(source_id, template_name);
104→
105→        let mut removed = false;
106→
107→        if content_path.exists() {
108→            fs::remove_file(&content_path)?;
109→            removed = true;
110→        }
111→
112→        if meta_path.exists() {
113→            fs::remove_file(&meta_path)?;
114→            removed = true;
115→        }
116→
117→        Ok(removed)
118→    }
119→
120→    /// List all cached entries.
121→    pub fn list(&self) -> Result<Vec<CacheEntry>> {
122→        self.ensure_dir()?;
123→
124→        let mut entries = Vec::new();
125→
126→        for entry in fs::read_dir(&self.root)? {
127→            let entry = entry?;
128→            let path = entry.path();
129→
130→            if path.extension().is_some_and(|e| e == "json") {
131→                if let Ok(json) = fs::read_to_string(&path) {
132→                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
133→                        entries.push(cache_entry);
134→                    }
135→                }
136→            }
137→        }
138→
139→        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
140→        Ok(entries)
141→    }
142→
143→    /// Clear all cached entries.
144→    pub fn clear(&self) -> Result<usize> {
145→        let entries = self.list()?;
146→        let count = entries.len();
147→
148→        for entry in entries {
149→            let _ = self.remove(&entry.source_id, &entry.template_name);
150→        }
151→
152→        Ok(count)
153→    }
154→
155→    /// Get total cache size in bytes.
156→    pub fn total_size(&self) -> Result<u64> {
157→        let entries = self.list()?;
158→        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
159→    }
160→}
161→
