  1→//! HTTP template fetching.
  2→//!
  3→//! Provides an HTTP client for fetching templates from URLs with
  4→//! support for ETag-based conditional requests.
  5→
  6→use crate::error::{BivvyError, Result};
  7→use reqwest::blocking::Client;
  8→use std::time::Duration;
  9→
 10→/// Default maximum response body size (10 MB).
 11→const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
 12→
 13→/// Fetches templates over HTTP/HTTPS.
 14→pub struct HttpFetcher {
 15→    client: Client,
 16→    timeout: Duration,
 17→    max_response_size: u64,
 18→}
 19→
 20→/// Response from fetching a template.
 21→#[derive(Debug)]
 22→pub struct FetchResponse {
 23→    /// The template content.
 24→    pub content: String,
 25→    /// ETag header if present.
 26→    pub etag: Option<String>,
 27→    /// Last-Modified header if present.
 28→    pub last_modified: Option<String>,
 29→}
 30→
 31→impl HttpFetcher {
 32→    /// Create a new HTTP fetcher with default 30-second timeout.
 33→    pub fn new() -> Self {
 34→        Self::with_timeout(Duration::from_secs(30))
 35→    }
 36→
 37→    /// Create a new HTTP fetcher with custom timeout.
 38→    pub fn with_timeout(timeout: Duration) -> Self {
 39→        Self {
 40→            client: Client::builder()
 41→                .user_agent("bivvy")
 42→                .timeout(timeout)
 43→                .build()
 44→                .expect("Failed to build HTTP client"),
 45→            timeout,
 46→            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
 47→        }
 48→    }
 49→
 50→    /// Create a new HTTP fetcher with custom timeout and max response size.
 51→    #[cfg(test)]
 52→    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
 53→        Self {
 54→            client: Client::builder()
 55→                .user_agent("bivvy")
 56→                .timeout(timeout)
 57→                .build()
 58→                .expect("Failed to build HTTP client"),
 59→            timeout,
 60→            max_response_size,
 61→        }
 62→    }
 63→
 64→    /// Get the configured timeout.
 65→    pub fn timeout(&self) -> Duration {
 66→        self.timeout
 67→    }
 68→
 69→    /// Fetch a template from a URL.
 70→    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
 71→        let response = self.client.get(url).send().map_err(|e| BivvyError::Http { url: url.to_string(), message: e.to_string() })?;
 72→
 73→        if !response.status().is_success() {
 74→            return Err(BivvyError::Http { url: url.to_string(), message: format!("HTTP {}", response.status()) });
 75→        }
 76→
 77→        // Check Content-Length if available
 78→        if let Some(len) = response.content_length() {
 79→            if len > self.max_response_size {
 80→                return Err(BivvyError::Http { url: url.to_string(), message: format!("Response too large ({} bytes, max {} bytes)", len, self.max_response_size) });
 81→            }
 82→        }
 83→
 84→        let etag = response
 85→            .headers()
 86→            .get("etag")
 87→            .and_then(|v| v.to_str().ok())
 88→            .map(String::from);
 89→
 90→        let last_modified = response
 91→            .headers()
 92→            .get("last-modified")
 93→            .and_then(|v| v.to_str().ok())
 94→            .map(String::from);
 95→
 96→        let content = response.text().map_err(|e| BivvyError::Http { url: url.to_string(), message: e.to_string() })?;
 97→
 98→        // Also check actual content size (in case Content-Length was missing/wrong)
 99→        if content.len() as u64 > self.max_response_size {
100→            return Err(BivvyError::Http { url: url.to_string(), message: format!("Response too large ({} bytes, max {} bytes)", content.len(), self.max_response_size) });
101→        }
102→
103→        Ok(FetchResponse {
104→            content,
105→            etag,
106→            last_modified,
107→        })
108→    }
109→
110→    /// Fetch with conditional request (If-None-Match).
111→    ///
112→    /// Returns `None` if content unchanged (304 Not Modified).
113→    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
114→        let mut request = self.client.get(url);
115→
116→        if let Some(etag) = etag {
117→            request = request.header("If-None-Match", etag);
118→        }
119→
120→        let response = request.send().map_err(|e| BivvyError::Http { url: url.to_string(), message: e.to_string() })?;
121→
122→        if response.status() == reqwest::StatusCode::NOT_MODIFIED {
123→            return Ok(None);
124→        }
125→
126→        if !response.status().is_success() {
127→            return Err(BivvyError::Http { url: url.to_string(), message: format!("HTTP {}", response.status()) });
128→        }
129→
130→        // Check Content-Length if available
131→        if let Some(len) = response.content_length() {
132→            if len > self.max_response_size {
133→                return Err(BivvyError::Http { url: url.to_string(), message: format!("Response too large ({} bytes, max {} bytes)", len, self.max_response_size) });
134→            }
135→        }
136→
137→        let new_etag = response
138→            .headers()
139→            .get("etag")
140→            .and_then(|v| v.to_str().ok())
141→            .map(String::from);
142→
143→        let last_modified = response
144→            .headers()
145→            .get("last-modified")
146→            .and_then(|v| v.to_str().ok())
147→            .map(String::from);
148→
149→        let content = response.text().map_err(|e| BivvyError::Http { url: url.to_string(), message: e.to_string() })?;
150→
151→        // Also check actual content size
152→        if content.len() as u64 > self.max_response_size {
153→            return Err(BivvyError::Http { url: url.to_string(), message: format!("Response too large ({} bytes, max {} bytes)", content.len(), self.max_response_size) });
154→        }
155→
156→        Ok(Some(FetchResponse {
157→            content,
158→            etag: new_etag,
159→            last_modified,
160→        }))
161→    }
162→}
163→
164→impl Default for HttpFetcher {
165→    fn default() -> Self {
166→        Self::new()
167→    }
168→}
