  1→//! Git template fetching.
  2→//!
  3→//! Provides functionality for cloning and updating git repositories
  4→//! to fetch templates, with support for specific refs and update detection.
  5→
  6→use crate::error::{BivvyError, Result};
  7→use sha2::{Digest, Sha256};
  8→use std::path::{Path, PathBuf};
  9→
 10→/// Fetches templates from git repositories.
 11→pub struct GitFetcher {
 12→    /// Directory for cloned repositories.
 13→    clone_dir: PathBuf,
 14→}
 15→
 16→/// Information about a git fetch.
 17→#[derive(Debug)]
 18→pub struct GitFetchResult {
 19→    /// Path to the fetched content.
 20→    pub local_path: PathBuf,
 21→    /// Current commit SHA.
 22→    pub commit_sha: String,
 23→}
 24→
 25→impl GitFetcher {
 26→    /// Create a new git fetcher.
 27→    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
 28→        Self {
 29→            clone_dir: clone_dir.into(),
 30→        }
 31→    }
 32→
 33→    /// Get the clone directory.
 34→    pub fn clone_dir(&self) -> &PathBuf {
 35→        &self.clone_dir
 36→    }
 37→
 38→    /// Clone or update a repository.
 39→    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
 40→        let repo_path = self.repo_path(url);
 41→
 42→        if repo_path.exists() {
 43→            self.update_repo(&repo_path, git_ref)?;
 44→        } else {
 45→            self.clone_repo(url, &repo_path, git_ref)?;
 46→        }
 47→
 48→        let commit_sha = self.get_head_sha(&repo_path)?;
 49→
 50→        Ok(GitFetchResult {
 51→            local_path: repo_path,
 52→            commit_sha,
 53→        })
 54→    }
 55→
 56→    /// Check if a repository has new commits.
 57→    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
 58→        let remote_sha = self.resolve_ref(url, git_ref)?;
 59→        Ok(remote_sha != current_sha)
 60→    }
 61→
 62→    /// Get the current commit SHA for a ref using ls-remote.
 63→    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
 64→        let refspec = git_ref.unwrap_or("HEAD");
 65→
 66→        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
 67→        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
 68→        let candidates = if refspec == "HEAD" {
 69→            vec![refspec.to_string()]
 70→        } else {
 71→            vec![
 72→                refspec.to_string(),
 73→                format!("refs/heads/{refspec}"),
 74→                format!("refs/tags/{refspec}"),
 75→            ]
 76→        };
 77→
 78→        for candidate in &candidates {
 79→            let output = std::process::Command::new("git")
 80→                .args(["ls-remote", url, candidate])
 81→                .output()?;
 82→
 83→            if !output.status.success() {
 84→                return Err(BivvyError::Git {
 85→                    message: format!(
 86→                        "Failed to query remote: {}",
 87→                        String::from_utf8_lossy(&output.stderr)
 88→                    ),
 89→                });
 90→            }
 91→
 92→            let stdout = String::from_utf8_lossy(&output.stdout);
 93→            if let Some(sha) = stdout
 94→                .lines()
 95→                .next()
 96→                .and_then(|line| line.split_whitespace().next())
 97→            {
 98→                return Ok(sha.to_string());
 99→            }
100→        }
101→
102→        return Err(BivvyError::Git {
103→            message: format!("Could not resolve ref '{}' from {}", refspec, url),
104→        })
105→    }
106→
107→    fn clone_repo(&self, url: &str, path: &Path, git_ref: Option<&str>) -> Result<()> {
108→        if let Some(parent) = path.parent() {
109→            std::fs::create_dir_all(parent)?;
110→        }
111→
112→        let mut cmd = std::process::Command::new("git");
113→        cmd.args(["clone", "--depth", "1"]);
114→
115→        if let Some(r) = git_ref {
116→            cmd.args(["--branch", r]);
117→        }
118→
119→        cmd.args([url, &path.to_string_lossy()]);
120→
121→        let output = cmd.output()?;
122→        if !output.status.success() {
123→            return Err(BivvyError::Git {
124→                message: format!(
125→                    "Git clone failed: {}",
126→                    String::from_utf8_lossy(&output.stderr)
127→                ),
128→            });
129→        }
130→
131→        Ok(())
132→    }
133→
134→    fn update_repo(&self, path: &PathBuf, git_ref: Option<&str>) -> Result<()> {
135→        let output = std::process::Command::new("git")
136→            .args(["fetch", "origin"])
137→            .current_dir(path)
138→            .output()?;
139→
140→        if !output.status.success() {
141→            return Err(BivvyError::Git {
142→                message: format!(
143→                    "Git fetch failed: {}",
144→                    String::from_utf8_lossy(&output.stderr)
145→                ),
146→            });
147→        }
148→
149→        let refspec = if let Some(r) = git_ref {
150→            format!("origin/{}", r)
151→        } else {
152→            "origin/HEAD".to_string()
153→        };
154→
155→        let output = std::process::Command::new("git")
156→            .args(["reset", "--hard", &refspec])
157→            .current_dir(path)
158→            .output()?;
159→
160→        if !output.status.success() {
161→            return Err(BivvyError::Git {
162→                message: format!(
163→                    "Git reset failed: {}",
164→                    String::from_utf8_lossy(&output.stderr)
165→                ),
166→            });
167→        }
168→
169→        Ok(())
170→    }
171→
172→    fn get_head_sha(&self, path: &PathBuf) -> Result<String> {
173→        let output = std::process::Command::new("git")
174→            .args(["rev-parse", "HEAD"])
175→            .current_dir(path)
176→            .output()?;
177→
178→        if !output.status.success() {
179→            return Err(BivvyError::Git {
180→                message: "Git rev-parse failed".to_string(),
181→            });
182→        }
183→
184→        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
185→    }

  1→//! Remote template loading from HTTP sources.
  2→//!
  3→//! Fetches templates from HTTP URLs defined in `template_sources`
  4→//! and caches them using the shared cache infrastructure.
  5→
  6→use anyhow::{Context, Result};
  7→use std::collections::HashMap;
  8→
  9→use super::fetch::HttpFetcher;
 10→use super::template::Template;
 11→use crate::cache::{parse_ttl, CacheStore};
 12→use crate::config::schema::TemplateSource as TemplateSourceConfig;
 13→
 14→/// Loads templates from remote HTTP sources with caching.
 15→#[derive(Debug, Clone)]
 16→pub struct RemoteLoader {
 17→    /// Fetched and parsed templates, keyed by name.
 18→    templates: HashMap<String, (Template, u32)>,
 19→}
 20→
 21→impl RemoteLoader {
 22→    /// Create a new remote loader by fetching templates from the given sources.
 23→    pub fn new(
 24→        sources: &[TemplateSourceConfig],
 25→        fetcher: &HttpFetcher,
 26→        cache: &CacheStore,
 27→    ) -> Result<Self> {
 28→        let mut templates = HashMap::new();
 29→
 30→        for source in sources {
 31→            match Self::load_source(source, fetcher, cache) {
 32→                Ok(loaded) => {
 33→                    for template in loaded {
 34→                        // Only insert if not already present (higher priority wins)
 35→                        templates
 36→                            .entry(template.name.clone())
 37→                            .or_insert((template, source.priority));
 38→                    }
 39→                }
 40→                Err(e) => {
 41→                    tracing::warn!("Failed to load templates from {}: {}", source.url, e);
 42→                }
 43→            }
 44→        }
 45→
 46→        Ok(Self { templates })
 47→    }
 48→
 49→    /// Create an empty remote loader (no sources).
 50→    pub fn empty() -> Self {
 51→        Self {
 52→            templates: HashMap::new(),
 53→        }
 54→    }
 55→
 56→    /// Load templates from a single source.
 57→    fn load_source(
 58→        source: &TemplateSourceConfig,
 59→        fetcher: &HttpFetcher,
 60→        cache: &CacheStore,
 61→    ) -> Result<Vec<Template>> {
 62→        let source_id = format!("http:{}", source.url);
 63→
 64→        // Check cache first
 65→        if let Some(entry) = cache.load(&source_id, "_index")? {
 66→            if !entry.is_expired() {
 67→                let content = cache.read_content(&entry)?;
 68→                return Self::parse_templates(&content);
 69→            }
 70→        }
 71→
 72→        // Fetch from remote
 73→        let response = fetcher
 74→            .fetch(&source.url)
 75→            .with_context(|| format!("Failed to fetch template source: {}", source.url))?;
 76→
 77→        // Cache the response
 78→        let ttl_seconds = source
 79→            .cache
 80→            .as_ref()
 81→            .and_then(|c| parse_ttl(&c.ttl).ok())
 82→            .map(|d| d.num_seconds() as u64)
 83→            .unwrap_or(604800);
 84→        cache.store(&source_id, "_index", &response.content, ttl_seconds)?;
 85→
 86→        Self::parse_templates(&response.content)
 87→    }
 88→
 89→    /// Parse a YAML response containing one or more templates.
 90→    ///
 91→    /// Supports two formats:
 92→    /// 1. A single template YAML document
 93→    /// 2. A YAML array of templates
 94→    fn parse_templates(content: &str) -> Result<Vec<Template>> {
 95→        // Try parsing as a list first
 96→        if let Ok(templates) = serde_yaml::from_str::<Vec<Template>>(content) {
 97→            return Ok(templates);
 98→        }
 99→
100→        // Try as a single template
101→        if let Ok(template) = serde_yaml::from_str::<Template>(content) {
102→            return Ok(vec![template]);
103→        }
104→
105→        anyhow::bail!(
106→            "Remote source returned content that is neither a template nor a list of templates"
107→        )
108→    }
109→
110→    /// Get a template by name.
111→    pub fn get(&self, name: &str) -> Option<&Template> {
112→        self.templates.get(name).map(|(t, _)| t)
113→    }
114→
115→    /// Get a template with its priority.
116→    pub fn get_with_priority(&self, name: &str) -> Option<(&Template, u32)> {
117→        self.templates.get(name).map(|(t, p)| (t, *p))
118→    }
119→
120→    /// Check if a template exists.
121→    pub fn has(&self, name: &str) -> bool {
122→        self.templates.contains_key(name)
123→    }
124→
125→    /// Get all template names.
126→    pub fn template_names(&self) -> Vec<&str> {
127→        self.templates.keys().map(|s| s.as_str()).collect()
128→    }
129→}
130→
131→#[cfg(test)]
132→mod tests {
133→    use super::*;
134→
135→    #[test]
136→    fn empty_loader_has_no_templates() {
137→        let loader = RemoteLoader::empty();
138→        assert!(!loader.has("anything"));
139→        assert!(loader.template_names().is_empty());
140→    }
141→
142→    #[test]
143→    fn parse_single_template() {
144→        let yaml = r#"
145→name: remote-tool
146→description: "A remote tool"
147→category: tools
148→step:
149→  command: echo hello
150→"#;
151→
152→        let templates = RemoteLoader::parse_templates(yaml).unwrap();
153→        assert_eq!(templates.len(), 1);
154→        assert_eq!(templates[0].name, "remote-tool");
155→    }
