164→    command: echo a
165→- name: tool-b
166→  description: "Tool B"
167→  category: tools
168→  step:
169→    command: echo b
170→"#;
171→
172→        let templates = RemoteLoader::parse_templates(yaml).unwrap();
173→        assert_eq!(templates.len(), 2);
174→        assert_eq!(templates[0].name, "tool-a");
175→        assert_eq!(templates[1].name, "tool-b");
176→    }
177→
178→    #[test]
179→    fn parse_invalid_content_returns_error() {
180→        let result = RemoteLoader::parse_templates("not a template at all: [[[");
181→        assert!(result.is_err());
182→    }
183→}
