  1→//! Configuration inheritance resolution.
  2→//!
  3→//! This module handles the `extends:` configuration feature, which allows
  4→//! configs to inherit from remote base configurations.
  5→
  6→use std::collections::HashSet;
  7→use std::time::Duration;
  8→
  9→use crate::error::{BivvyError, Result};
 10→
 11→use super::merger::deep_merge_with_leaves;
 12→use super::remote::RemoteFetcher;
 13→use super::schema::{BivvyConfig, ExtendsConfig};
 14→
 15→/// Resolves configuration inheritance chain.
 16→///
 17→/// # Example
 18→///
 19→/// ```no_run
 20→/// use bivvy::config::{BivvyConfig, ExtendsResolver};
 21→///
 22→/// let resolver = ExtendsResolver::new();
 23→///
 24→/// // Resolve a config that extends a remote base
 25→/// let config: BivvyConfig = serde_yaml::from_str(r#"
 26→/// extends:
 27→///   - url: https://example.com/base-config.yml
 28→/// app_name: MyApp
 29→/// "#).unwrap();
 30→///
 31→/// let resolved = resolver.resolve(&config).unwrap();
 32→/// ```
 33→pub struct ExtendsResolver {
 34→    fetcher: RemoteFetcher,
 35→    max_depth: usize,
 36→}
 37→
 38→impl ExtendsResolver {
 39→    /// Create a resolver with default settings.
 40→    pub fn new() -> Self {
 41→        Self {
 42→            fetcher: RemoteFetcher::new(Duration::from_secs(30)),
 43→            max_depth: 10,
 44→        }
 45→    }
 46→
 47→    /// Create a resolver with a custom fetcher.
 48→    pub fn with_fetcher(fetcher: RemoteFetcher) -> Self {
 49→        Self {
 50→            fetcher,
 51→            max_depth: 10,
 52→        }
 53→    }
 54→
 55→    /// Create a resolver with custom max depth.
 56→    pub fn with_max_depth(max_depth: usize) -> Self {
 57→        Self {
 58→            fetcher: RemoteFetcher::default(),
 59→            max_depth,
 60→        }
 61→    }
 62→
 63→    /// Resolve all extends references and merge configs.
 64→    pub fn resolve(&self, config: &BivvyConfig) -> Result<BivvyConfig> {
 65→        self.resolve_with_visited(config, &mut HashSet::new(), 0)
 66→    }
 67→
 68→    fn resolve_with_visited(
 69→        &self,
 70→        config: &BivvyConfig,
 71→        visited: &mut HashSet<String>,
 72→        depth: usize,
 73→    ) -> Result<BivvyConfig> {
 74→        if depth > self.max_depth {
 75→            return Err(BivvyError::ConfigValidationError {
 76→                message: format!("Config extends depth exceeds maximum of {}", self.max_depth),
 77→            });
 78→        }
 79→
 80→        // If no extends, return config as-is
 81→        let extends = match &config.extends {
 82→            Some(e) if !e.is_empty() => e,
 83→            _ => return Ok(config.clone()),
 84→        };
 85→
 86→        // Convert current config to Value for merging
 87→        let config_value = serde_yaml::to_value(config).map_err(|e| BivvyError::Serialization { message: e.to_string() })?;
 88→
 89→        // Environment override blocks should replace entirely, not field-merge
 90→        let leaf_keys = std::collections::HashSet::from(["environments"]);
 91→
 92→        // Start with empty Value
 93→        let mut merged = serde_yaml::Value::Mapping(serde_yaml::Mapping::new());
 94→
 95→        // Process each base config in order
 96→        for ext in extends {
 97→            // Check for cycles
 98→            if visited.contains(&ext.url) {
 99→                return Err(BivvyError::ConfigValidationError {
100→                    message: format!("Circular extends detected: {}", ext.url),
101→                });
102→            }
103→            visited.insert(ext.url.clone());
104→
105→            // Fetch and parse base config
106→            let content = self.fetcher.fetch(&ext.url)?;
107→            let base_config: BivvyConfig = serde_yaml::from_str(&content).map_err(|e| BivvyError::Serialization { message: e.to_string() })?;
108→
109→            // Recursively resolve base's extends
110→            let resolved_base = self.resolve_with_visited(&base_config, visited, depth + 1)?;
111→
112→            // Convert to Value and merge
113→            let base_value = serde_yaml::to_value(&resolved_base).map_err(|e| BivvyError::Serialization { message: e.to_string() })?;
114→            merged = deep_merge_with_leaves(&merged, &base_value, &leaf_keys);
115→        }
116→
117→        // Finally merge the current config on top
118→        let final_value = deep_merge_with_leaves(&merged, &config_value, &leaf_keys);
119→
120→        // Deserialize back to BivvyConfig
121→        let mut final_config: BivvyConfig = serde_yaml::from_value(final_value).map_err(|e| BivvyError::Serialization { message: e.to_string() })?;
122→
123→        // Clear extends from final config (already resolved)
124→        final_config.extends = None;
125→
126→        Ok(final_config)
127→    }
128→
129→    /// Get the maximum extends depth.
130→    pub fn max_depth(&self) -> usize {
131→        self.max_depth
132→    }
133→}
134→
135→impl Default for ExtendsResolver {
136→    fn default() -> Self {
137→        Self::new()
138→    }
139→}
140→
141→/// Known private/internal hostnames that should be blocked for SSRF prevention.
142→const BLOCKED_HOSTS: &[&str] = &["localhost", "127.0.0.1", "0.0.0.0", "[::1]"];
143→
144→/// Known cloud metadata IP addresses.
145→const BLOCKED_IPS: &[&str] = &["169.254.169.254", "100.100.100.200"];
146→
147→/// Extract the host from an HTTP/HTTPS URL.
148→fn extract_host(url: &str) -> Option<String> {
149→    // Strip scheme
150→    let without_scheme = url
151→        .strip_prefix("https://")
152→        .or_else(|| url.strip_prefix("http://"))?;
153→    // Take everything before the first '/' or end
154→    let host_port = without_scheme.split('/').next()?;
155→    // Strip port if present
156→    let host = if host_port.starts_with('[') {
157→        // IPv6: [::1]:8080
158→        host_port.split(']').next().map(|h| format!("{}]", h))
159→    } else {
160→        Some(host_port.split(':').next().unwrap_or(host_port).to_string())
161→    };
162→    host
163→}
164→
165→/// Validate extends configuration.
166→pub fn validate_extends(extends: &[ExtendsConfig]) -> Result<()> {
167→    for ext in extends {
168→        if ext.url.is_empty() {
169→            return Err(BivvyError::ConfigValidationError {
170→                message: "Extends URL cannot be empty".to_string(),
171→            });
172→        }
173→        if !ext.url.starts_with("http://") && !ext.url.starts_with("https://") {
174→            return Err(BivvyError::ConfigValidationError {
175→                message: format!("Extends URL must be HTTP/HTTPS: {}", ext.url),
176→            });
177→        }
178→        // SSRF prevention: block private/internal addresses
179→        if let Some(host) = extract_host(&ext.url) {
180→            let host_lower = host.to_lowercase();
181→            if BLOCKED_HOSTS.iter().any(|&h| host_lower == h) {
182→                return Err(BivvyError::ConfigValidationError {
183→                    message: format!(
184→                        "Extends URL must not reference localhost or loopback addresses: {}",
185→                        ext.url
186→                    ),
187→                });
188→            }
189→            if BLOCKED_IPS.iter().any(|&ip| host_lower == ip) {
190→                return Err(BivvyError::ConfigValidationError {
191→                    message: format!(
192→                        "Extends URL must not reference internal/metadata IP addresses: {}",
193→                        ext.url
194→                    ),
195→                });
196→            }
197→            // Block 10.x.x.x, 172.16-31.x.x, 192.168.x.x ranges
198→            if let Ok(ip) = host.parse::<std::net::Ipv4Addr>() {
199→                if ip.is_private() || ip.is_loopback() || ip.is_link_local() {
200→                    return Err(BivvyError::ConfigValidationError {
201→                        message: format!(
202→                            "Extends URL must not reference private IP addresses: {}",
203→                            ext.url
204→                        ),
205→                    });
206→                }
207→            }
208→        }
209→    }
210→    Ok(())
211→}
